def find_good_numbers():
    good_numbers = set()
    count = 0

    # Iterate over x < y to ensure distinct positive integers
    # We need to find the 20th smallest, so we need a reasonable upper bound.
    # The 20th number was 68. Let's go up to 100 for safety.
    MAX_VAL = 100 

    for x in range(1, MAX_VAL):
        for y in range(x + 1, MAX_VAL):
            m = x**2 + y**2
            if m > 0:
                good_numbers.add(m)

    sorted_numbers = sorted(list(good_numbers))

    # Check if we found at least 20 numbers
    if len(sorted_numbers) >= 20:
        print(f"List of the first 25 good numbers: {sorted_numbers[:25]}")
        print(f"The 20th smallest good number is: {sorted_numbers[19]}")
    else:
        print("Not enough good numbers found within the limit.")

